const data = $input.first().json.output || { overallNote: "", picks: [] };
const picks = data.picks || [];
const skyBlue = "#0EA5E9";
const orange = "#F97316";
const darkNavy = "#0B2545";

const cardsHtml = picks.map(function(p) {
  return '<div style="border:1px solid #e2e8f0;border-left:6px solid ' + orange + ';border-radius:8px;padding:16px;margin-bottom:14px;background:#ffffff;">' +
    '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">' +
    '<span style="font-weight:700;color:' + darkNavy + ';font-size:15px;">' + p.sport + ': ' + p.matchup + '</span>' +
    '<span style="background:' + skyBlue + ';color:#ffffff;font-size:11px;font-weight:700;padding:3px 10px;border-radius:999px;">' + (p.confidence || "").toUpperCase() + '</span>' +
    '</div>' +
    '<div style="color:' + orange + ';font-weight:700;font-size:14px;margin-bottom:4px;">Pick: ' + p.pick + ' (' + p.hardRockOdds + ') — edge +' + p.edgePct + '%</div>' +
    '<div style="color:#334155;font-size:13px;line-height:1.5;">' + p.rationale + '</div>' +
    '</div>';
}).join("");

const bodyContent = picks.length > 0 ? cardsHtml : '<p style="color:#334155;">No bets cleared review this run.</p>';

const html = '<div style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;max-width:600px;margin:0 auto;">' +
  '<div style="background:' + skyBlue + ';padding:20px 24px;border-radius:8px 8px 0 0;">' +
  '<h1 style="color:#ffffff;margin:0;font-size:20px;">Hard Rock Value Bets</h1>' +
  '<p style="color:#e0f2fe;margin:6px 0 0;font-size:13px;">' + (data.overallNote || "") + '</p>' +
  '</div>' +
  '<div style="padding:20px 24px;background:#f8fafc;">' + bodyContent + '</div>' +
  '<div style="padding:16px 24px;border-top:2px solid ' + orange + ';color:#94a3b8;font-size:11px;">Automated edge estimate based on Hard Rock vs. Pinnacle pricing, reviewed by an AI analyst step. Not financial advice, no guarantee of outcome. Bet responsibly.</div>' +
  '</div>';

return [{ json: { emailHtml: html, pickCount: picks.length } }];

const items = $input.all();
const feedbackRows = items.filter(function(item) { return item.json && item.json.receivedAt; }).map(function(item) {
  return {
    receivedAt: item.json.receivedAt,
    matchup: item.json.matchup,
    sentiment: item.json.sentiment,
    feedbackSummary: item.json.feedbackSummary
  };
});
return [{ json: { feedbackRows: feedbackRows } }];
